// src/components/ExtraCurricular.jsx
import React, { useRef, useEffect, useState } from "react";
import Banner from "./Banner";
import axios from "axios";
import "../styles/main.css";

const ExtraCurricular = () => {
  // refs for each section
  const sectionsRef = {
    foreignLanguages: useRef(null),
    ethics: useRef(null),
    sports: useRef(null),
    musicDance: useRef(null),
    artCraft: useRef(null),
    tourTrips: useRef(null),
  };

  const [content, setContent] = useState({
    foreignLanguages: "",
    ethics: "",
    sports: "",
    musicDance: "",
    artCraft: "",
    tourTrips: "",
  });

  // fetch editable content from backend
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/extracurricular")
      .then((res) => {
        if (res.data.success) setContent(res.data.data);
      })
      .catch((err) => console.error("Failed to fetch extra curricular content:", err));
  }, []);

  const scrollToSection = (key) => {
    sectionsRef[key].current.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <>
      <Banner />
      <div className="extra-page">
        <div className="left-column">
          <h2>Extra Curricular</h2>
          <div className="info-box">
            <p onClick={() => scrollToSection("foreignLanguages")}>Foreign Languages</p>
            <p onClick={() => scrollToSection("ethics")}>Ethics and Personality Development</p>
            <p onClick={() => scrollToSection("sports")}>Sports</p>
            <p onClick={() => scrollToSection("musicDance")}>Music & Dance</p>
            <p onClick={() => scrollToSection("artCraft")}>Art & Craft</p>
            <p onClick={() => scrollToSection("tourTrips")}>Tour & Trips</p>
          </div>
        </div>

        <div className="right-column">
          <h2>Extra Curricular</h2>

          <div ref={sectionsRef.foreignLanguages} className="section">
            <h3>Foreign Languages</h3>
            <div dangerouslySetInnerHTML={{ __html: content.foreignLanguages }} />
          </div>

          <div ref={sectionsRef.ethics} className="section">
            <h3>Ethics & Personality Development</h3>
            <div dangerouslySetInnerHTML={{ __html: content.ethics }} />
          </div>

          <div ref={sectionsRef.sports} className="section">
            <h3>Sports</h3>
            <div dangerouslySetInnerHTML={{ __html: content.sports }} />
          </div>

          <div ref={sectionsRef.musicDance} className="section">
            <h3>Music & Dance</h3>
            <div dangerouslySetInnerHTML={{ __html: content.musicDance }} />
          </div>

          <div ref={sectionsRef.artCraft} className="section">
            <h3>Art & Craft</h3>
            <div dangerouslySetInnerHTML={{ __html: content.artCraft }} />
          </div>

          <div ref={sectionsRef.tourTrips} className="section">
            <h3>Tour & Trips</h3>
            <div dangerouslySetInnerHTML={{ __html: content.tourTrips }} />
          </div>
        </div>
      </div>
    </>
  );
};

export default ExtraCurricular;
